"""The same structured external evidence, adapted to both native metric interfaces."""

import math

from deepeval.metrics import BaseMetric
from pydantic import BaseModel, ConfigDict
from ragas.metrics.collections.base import BaseMetric as RagasBaseMetric
from ragas.metrics.result import MetricResult


class Evidence(BaseModel):
    model_config = ConfigDict(extra="forbid", strict=True)
    status: str
    checks: dict[str, bool] = {}
    error: str | None = None

    def score(self):
        if self.status != "scored" or not self.checks:
            raise ValueError(self.error or "Evidence missing or outside verifier applicability")
        return float(all(self.checks.values()))


def evidence_score(data):
    return Evidence.model_validate(data).score()


class ExternalCompletionMetric(BaseMetric):
    def __init__(self):
        self.threshold, self.async_mode = 1.0, False

    def measure(self, test_case, **kwargs):
        self.score, self.error, self.reason = None, None, None
        try:
            data = (test_case.metadata or {})["external_evidence"]
            self.score = evidence_score(data)
            self.reason = (
                "All required external checks pass" if self.score else "External check failed"
            )
            return self.score
        except (ValueError, KeyError) as error:
            self.error = str(error)
            raise ValueError(self.error) from error

    async def a_measure(self, test_case, **kwargs):
        return self.measure(test_case, **kwargs)

    @property
    def __name__(self):
        return "External code completion"


class RagasExternalCompletion(RagasBaseMetric):
    def __init__(self):
        super().__init__(name="external_code_completion")

    async def ascore(self, evidence):
        value = evidence_score(evidence)
        return MetricResult(value=value, reason="Conjunction of required external checks")


def composite(rule_score, judge_score):
    if any(s is None for s in (rule_score, judge_score)):
        return {"status": "unscored", "score": None}
    if any(not math.isfinite(s) or not 0 <= s <= 1 for s in (rule_score, judge_score)):
        raise ValueError("Scores must be finite and within [0, 1]")
    return {"status": "scored", "score": min(rule_score, judge_score)}

runner.py:
"""Execute the declared pure-Python teaching subset in a bounded child process."""

import ast
import json
import resource
import sys

SAFE_BUILTINS = {
    f.__name__: f
    for f in (
        type,
        isinstance,
        int,
        bool,
        str,
        float,
        min,
        max,
        sum,
        len,
        range,
        abs,
        all,
        any,
        ValueError,
        TypeError,
        Exception,
    )
}
FORBIDDEN = (
    ast.Import,
    ast.ImportFrom,
    ast.Attribute,
    ast.Global,
    ast.Nonlocal,
    ast.ClassDef,
    ast.AsyncFunctionDef,
    ast.Await,
    ast.With,
    ast.Try,
)


def validate_source(source):
    tree = ast.parse(source)
    for node in ast.walk(tree):
        if isinstance(node, FORBIDDEN):
            raise TypeError(f"Outside declared teaching subset: {type(node).__name__}")
        if isinstance(node, ast.Name) and node.id.startswith("__"):
            raise ValueError("Dunder names are outside the declared subset")
    functions = [
        n for n in tree.body if isinstance(n, ast.FunctionDef) and n.name == "shipping_fee"
    ]
    if len(functions) != 1:
        raise ValueError("One top-level shipping_fee definition is required")
    args = functions[0].args
    if (
        [a.arg for a in args.args] != ["weight_grams", "expedited"]
        or args.posonlyargs
        or args.kwonlyargs
        or args.vararg
        or args.kwarg
        or len(args.defaults) != 1
        or not isinstance(args.defaults[0], ast.Constant)
        or args.defaults[0].value is not False
    ):
        raise ValueError("The required function signature must be preserved")
    return tree


def execute(source, cases):
    tree = validate_source(source)
    namespace = {"__builtins__": SAFE_BUILTINS.copy()}
    exec(compile(tree, "submitted-shipping.py", "exec"), namespace)  # noqa: S102
    function = namespace.get("shipping_fee")
    if not callable(function):
        raise TypeError("Missing shipping_fee function")
    results = []
    for case in cases:
        try:
            value = function(**case["arguments"])
            actual = {"value": value, "type": type(value).__name__}
        except Exception as error:  # noqa: BLE001 - submitted program exceptions are outcomes
            actual = {"exception": type(error).__name__}
        results.append(
            {
                "id": case["id"],
                "actual": actual,
                "expected": case["expected"],
                "passed": actual == case["expected"],
            }
        )
    return results


def main():
    resource.setrlimit(resource.RLIMIT_CPU, (2, 2))
    memory_bytes = 256 * 1024 * 1024 if sys.platform == "linux" else None
    if memory_bytes is not None:
        resource.setrlimit(resource.RLIMIT_AS, (memory_bytes,) * 2)
    payload = json.load(sys.stdin)
    try:
        results = execute(payload["source"], payload["cases"])
        output = {"status": "scored", "cases": results}
    except Exception as error:  # noqa: BLE001 - unsupported code is unscored, not a zero
        output = {"status": "unscored", "error": f"{type(error).__name__}: {error}"}
    output["limits"] = {"cpu_seconds": 2, "memory_bytes": memory_bytes, "platform": sys.platform}
    print(json.dumps(output, ensure_ascii=False, allow_nan=False))


if __name__ == "__main__":
    main()

